import {
  Chart as ChartJS,
  BarElement,
  CategoryScale,
  LinearScale,
  Tooltip,
  Legend
} from "chart.js";
import { Bar } from "react-chartjs-2";

ChartJS.register(
  BarElement,
  CategoryScale,
  LinearScale,
  Tooltip,
  Legend
);

export default function UsageBarChart({ data = [] }) {
  if (!Array.isArray(data) || data.length === 0) {
    return <p>No usage data available</p>;
  }

  return (
    <Bar
      data={{
        labels: data.map(d => d._id),
        datasets: [
          {
            label: "Productive Time (mins)",
            data: data.map(d => Math.round(d.productiveTime / 60))
          },
          {
            label: "Unproductive Time (mins)",
            data: data.map(d => Math.round(d.unproductiveTime / 60))
          }
        ]
      }}
      options={{
        responsive: true,
        plugins: {
          legend: {
            position: "bottom"
          }
        }
      }}
    />
  );
}
